#!/usr/bin/env bash
# Prepares the native iOS project on the Codemagic macOS machine.
#
# The repository is authored on Windows, where Xcode isn't available, so the
# ios/ folder is generated by Flutter on the build machine and then patched
# with Focus Reset's settings. Running it repeatedly is safe.
#
# Usage: bash scripts/prepare_ios.sh   (BUNDLE_ID env var optional)
set -euo pipefail

BUNDLE_ID="${BUNDLE_ID:-com.focusreset.app}"

if [ ! -d ios ]; then
  echo "ios/ not found — generating with flutter create"
  flutter create --platforms=ios --org com.focusreset --project-name focus_reset .
  # flutter create adds a default counter test that doesn't apply to this app.
  rm -f test/widget_test.dart
fi

PLIST="ios/Runner/Info.plist"
PB="/usr/libexec/PlistBuddy"

set_string () {
  $PB -c "Set :$1 '$2'" "$PLIST" 2>/dev/null || $PB -c "Add :$1 string '$2'" "$PLIST"
}
set_bool () {
  $PB -c "Set :$1 $2" "$PLIST" 2>/dev/null || $PB -c "Add :$1 bool $2" "$PLIST"
}

set_string CFBundleDisplayName "Focus Reset"
set_string CFBundleName "Focus Reset"
set_string CFBundleDevelopmentRegion "en"

# Declare both languages so iOS shows Arabic system UI (and App Store lists it).
$PB -c "Delete :CFBundleLocalizations" "$PLIST" 2>/dev/null || true
$PB -c "Add :CFBundleLocalizations array" "$PLIST"
$PB -c "Add :CFBundleLocalizations:0 string en" "$PLIST"
$PB -c "Add :CFBundleLocalizations:1 string ar" "$PLIST"

# Apple Calendar is read (never written) so tasks avoid existing events.
CAL_TEXT="Focus Reset reads your calendar events so it never schedules tasks over them. Nothing is changed or uploaded."
set_string NSCalendarsUsageDescription "$CAL_TEXT"
set_string NSCalendarsFullAccessUsageDescription "$CAL_TEXT"

# Only standard HTTPS encryption is used — no export-compliance questions.
set_bool ITSAppUsesNonExemptEncryption false

# iPhone, portrait only.
$PB -c "Delete :UISupportedInterfaceOrientations" "$PLIST" 2>/dev/null || true
$PB -c "Add :UISupportedInterfaceOrientations array" "$PLIST"
$PB -c "Add :UISupportedInterfaceOrientations:0 string UIInterfaceOrientationPortrait" "$PLIST"

PBX="ios/Runner.xcodeproj/project.pbxproj"
sed -i '' 's/TARGETED_DEVICE_FAMILY = "1,2";/TARGETED_DEVICE_FAMILY = 1;/g' "$PBX"
# Main app target, then the test target (keeps its .RunnerTests suffix).
sed -i '' -E "/RunnerTests/!s/PRODUCT_BUNDLE_IDENTIFIER = [A-Za-z0-9.-]+;/PRODUCT_BUNDLE_IDENTIFIER = ${BUNDLE_ID};/" "$PBX"
sed -i '' -E "s/PRODUCT_BUNDLE_IDENTIFIER = [A-Za-z0-9.-]+\.RunnerTests;/PRODUCT_BUNDLE_IDENTIFIER = ${BUNDLE_ID}.RunnerTests;/" "$PBX"

echo "iOS project ready — bundle id: ${BUNDLE_ID}"
